use serde_json::{json,Value};use std::{fs,io::{Read,Write,BufRead,BufReader},net::TcpListener,process::{Command,Stdio},os::unix::fs::PermissionsExt,sync::{Arc,atomic::{AtomicBool,Ordering},mpsc},thread,time::{Instant,Duration}};
#[test]
fn watch_delivers_subscription_message_before_poll_and_stops_on_hide(){
 let root=std::env::temp_dir().join(format!("t3-live-test-{}",uuid::Uuid::new_v4()));fs::create_dir_all(&root).unwrap();let token=root.join("token");fs::write(&token,"synthetic-token").unwrap();fs::set_permissions(&token,fs::Permissions::from_mode(0o600)).unwrap();let listener=TcpListener::bind("127.0.0.1:0").unwrap();listener.set_nonblocking(true).unwrap();let base=format!("http://{}",listener.local_addr().unwrap());let config=root.join("env.json");fs::write(&config,json!({"environments":[{"id":"fixture","name":"Fixture","base_url":base,"token_file":token}]}).to_string()).unwrap();let stop=Arc::new(AtomicBool::new(false));let server_stop=stop.clone();let socket_closed=Arc::new(AtomicBool::new(false));let closed=socket_closed.clone();
 let server=thread::spawn(move||{while !server_stop.load(Ordering::Relaxed){if let Ok((mut s,_))=listener.accept(){let closed=closed.clone();thread::spawn(move||{s.set_read_timeout(Some(Duration::from_secs(3))).unwrap();let mut peek=[0;1024];let n=s.peek(&mut peek).unwrap_or(0);let request=String::from_utf8_lossy(&peek[..n]);if request.starts_with("GET /ws") {let mut ws=tungstenite::accept(s).unwrap();let req:Value=serde_json::from_str(ws.read().unwrap().to_text().unwrap()).unwrap();if req["tag"]=="server.getConfig"{let _=ws.send(tungstenite::Message::Text(json!({"_tag":"Exit","requestId":"1","exit":{"_tag":"Success","value":{"threadResumeCompletionMarker":true}}}).to_string().into()));return}if req["tag"]=="orchestration.subscribeShell"{return}assert_eq!(req["tag"],"orchestration.subscribeThread");assert_eq!(req["payload"]["requestCompletionMarker"],true);assert_eq!(req["payload"]["afterSequence"],0);assert_eq!(req["payload"]["acceptCompactTurnItems"],true);ws.send(tungstenite::Message::Text(json!({"_tag":"Chunk","requestId":"1","values":[{"kind":"synchronized"}]}).to_string().into())).unwrap();let _=ws.read();thread::sleep(Duration::from_millis(90));let update=json!({"kind":"event","sequence":1,"event":{"type":"message.updated","payload":{"id":"new","role":"assistant","text":"streamed immediately","createdAt":2000,"attachments":[]}}});ws.send(tungstenite::Message::Text(json!({"_tag":"Chunk","requestId":"1","values":[update.clone(),update]}).to_string().into())).unwrap();loop{match ws.read(){Ok(tungstenite::Message::Close(_))|Err(_)=>break,Ok(tungstenite::Message::Text(t))=>{let v:Value=serde_json::from_str(&t).unwrap();if v["_tag"]=="Interrupt"{break}},_=>{}}}closed.store(true,Ordering::Relaxed);
 }else{let mut data=[0;8192];let _=s.read(&mut data);let body=if request.contains("/bounded"){json!({"snapshotSequence":0,"projection":{"thread":{"id":"one"},"messages":[{"id":"old","role":"user","text":"hello","createdAt":1000}],"runs":[],"turnItems":[]}})}else{json!({"threads":[{"id":"one","title":"One","updatedAt":1000}],"projects":[]})};let body=body.to_string();write!(s,"HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",body.len(),body).unwrap();}});}else{thread::sleep(Duration::from_millis(5));}}});
 let mut child=Command::new(env!("CARGO_BIN_EXE_omarchy-t3-client")).arg("watch").env("HOME",root.join("home")).env("T3CODE_HOME",root.join("native")).env("XDG_STATE_HOME",root.join("state")).env("OMARCHY_T3_FIXTURE_ENVIRONMENTS",config).env_remove("OPENCODE_API_KEY").env_remove("OPENCODE_GO_API_KEY").env_remove("KIMI_CODING_API_KEY").env_remove("NOUS_API_KEY").stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::null()).spawn().unwrap();let mut input=child.stdin.take().unwrap();let (tx,rx)=mpsc::channel();let output=child.stdout.take().unwrap();thread::spawn(move||for line in BufReader::new(output).lines().map_while(Result::ok){if let Ok(v)=serde_json::from_str::<Value>(&line){let _=tx.send(v);}});
 writeln!(input,"{}",json!({"op":"visible","value":true})).unwrap();let start=Instant::now();writeln!(input,"{}",json!({"op":"select","environment":"fixture","thread":"one","serial":73})).unwrap();loop{let v=rx.recv_timeout(Duration::from_secs(3)).unwrap();if v["type"]=="messages"&&v["data"]["result"]["messages"].as_array().is_some_and(|ms|ms.iter().any(|m|m["text"]=="streamed immediately")){assert_eq!(v["data"]["serial"],73);assert_eq!(v["data"]["result"]["messages"].as_array().unwrap().len(),2);assert!(start.elapsed()<Duration::from_secs(2));break}}
 writeln!(input,"{}",json!({"op":"visible","value":false})).unwrap();for _ in 0..50{if socket_closed.load(Ordering::Relaxed){break}thread::sleep(Duration::from_millis(10));}assert!(socket_closed.load(Ordering::Relaxed));writeln!(input,"{}",json!({"op":"quit"})).unwrap();child.wait().unwrap();stop.store(true,Ordering::Relaxed);server.join().unwrap();fs::remove_dir_all(root).unwrap();
}

/// A reconnect to the open chat resumes after the last applied sequence without
/// downloading the bounded snapshot again; an event type this build does not know
/// still moves the cursor.
#[test]
fn reconnect_resumes_from_the_held_sequence_without_a_second_bounded_read(){
 let root=std::env::temp_dir().join(format!("t3-live-resume-{}",uuid::Uuid::new_v4()));fs::create_dir_all(&root).unwrap();let token=root.join("token");fs::write(&token,"synthetic-token").unwrap();fs::set_permissions(&token,fs::Permissions::from_mode(0o600)).unwrap();
 let listener=TcpListener::bind("127.0.0.1:0").unwrap();listener.set_nonblocking(true).unwrap();let base=format!("http://{}",listener.local_addr().unwrap());let config=root.join("env.json");fs::write(&config,json!({"environments":[{"id":"fixture","name":"Fixture","base_url":base,"token_file":token}]}).to_string()).unwrap();
 let stop=Arc::new(AtomicBool::new(false));let bounded=Arc::new(std::sync::atomic::AtomicUsize::new(0));let cursors=Arc::new(std::sync::Mutex::new(Vec::<Value>::new()));
 let (server_stop,bounded_reads,seen)=(stop.clone(),bounded.clone(),cursors.clone());
 let message=|seq:u64,id:&str,text:&str|json!({"kind":"event","sequence":seq,"event":{"type":"message.updated","payload":{"id":id,"role":"assistant","text":text,"createdAt":2000+seq,"attachments":[]}}});
 let server=thread::spawn(move||{while !server_stop.load(Ordering::Relaxed){let Ok((mut s,_))=listener.accept() else{thread::sleep(Duration::from_millis(5));continue};let (bounded_reads,seen,server_stop)=(bounded_reads.clone(),seen.clone(),server_stop.clone());thread::spawn(move||{
  s.set_nonblocking(false).unwrap();s.set_read_timeout(Some(Duration::from_secs(3))).unwrap();let mut peek=[0;1024];let n=s.peek(&mut peek).unwrap_or(0);let request=String::from_utf8_lossy(&peek[..n]).to_string();
  if !request.starts_with("GET /ws"){let mut data=[0;8192];let _=s.read(&mut data);let body=if request.contains("/bounded"){bounded_reads.fetch_add(1,Ordering::Relaxed);json!({"snapshotSequence":0,"projection":{"thread":{"id":"one"},"messages":[{"id":"old","role":"user","text":"hello","createdAt":1000}],"runs":[],"turnItems":[]}})}else{json!({"threads":[{"id":"one","title":"One","updatedAt":1000}],"projects":[]})}.to_string();let _=write!(s,"HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",body.len(),body);return}
  let mut ws=tungstenite::accept(s).unwrap();let req:Value=serde_json::from_str(ws.read().unwrap().to_text().unwrap()).unwrap();
  match req["tag"].as_str().unwrap_or(""){
   "server.getConfig"=>{let _=ws.send(tungstenite::Message::Text(json!({"_tag":"Exit","requestId":"1","exit":{"_tag":"Success","value":{"threadResumeCompletionMarker":true}}}).to_string().into()));}
   "orchestration.subscribeThread"=>{
    let round={let mut seen=seen.lock().unwrap();seen.push(req["payload"]["afterSequence"].clone());seen.len()};
    let values=match round{1=>json!([{"kind":"synchronized"},message(1,"a","first")]),2=>json!([{"kind":"synchronized"},{"kind":"event","sequence":2,"event":{"type":"thread.some-future-event","payload":{}}}]),_=>json!([{"kind":"synchronized"},message(3,"b","after reconnect")])};
    ws.send(tungstenite::Message::Text(json!({"_tag":"Chunk","requestId":"1","values":values}).to_string().into())).unwrap();
    if round<3{thread::sleep(Duration::from_millis(300));return}
    while !server_stop.load(Ordering::Relaxed){match ws.read(){Ok(tungstenite::Message::Text(t))=>{let v:Value=serde_json::from_str(&t).unwrap();if v["_tag"]=="Interrupt"{break}if v["_tag"]=="Ping"{let _=ws.send(tungstenite::Message::Text(json!({"_tag":"Pong"}).to_string().into()));}},Ok(tungstenite::Message::Close(_))=>break,Err(tungstenite::Error::Io(e)) if matches!(e.kind(),std::io::ErrorKind::WouldBlock|std::io::ErrorKind::TimedOut)=>{},Err(_)=>break,_=>{}}}
   }
   _=>{}
  }
 });}});
 let mut child=Command::new(env!("CARGO_BIN_EXE_omarchy-t3-client")).arg("watch").env("HOME",root.join("home")).env("T3CODE_HOME",root.join("native")).env("XDG_STATE_HOME",root.join("state")).env("OMARCHY_T3_FIXTURE_ENVIRONMENTS",config).env_remove("OPENCODE_API_KEY").env_remove("OPENCODE_GO_API_KEY").env_remove("KIMI_CODING_API_KEY").env_remove("NOUS_API_KEY").stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::null()).spawn().unwrap();
 let mut input=child.stdin.take().unwrap();let (tx,rx)=mpsc::channel();let output=child.stdout.take().unwrap();thread::spawn(move||for line in BufReader::new(output).lines().map_while(Result::ok){if let Ok(v)=serde_json::from_str::<Value>(&line){let _=tx.send(v);}});
 writeln!(input,"{}",json!({"op":"visible","value":true})).unwrap();writeln!(input,"{}",json!({"op":"select","environment":"fixture","thread":"one","serial":7})).unwrap();
 let start=Instant::now();
 loop{assert!(start.elapsed()<Duration::from_secs(15),"no resumed message");let Ok(v)=rx.recv_timeout(Duration::from_secs(15)) else{continue};if v["type"]=="messages"&&v["data"]["result"]["messages"].as_array().is_some_and(|ms|ms.iter().any(|m|m["text"]=="after reconnect")){let texts:Vec<_>=v["data"]["result"]["messages"].as_array().unwrap().iter().map(|m|m["text"].clone()).collect();assert_eq!(texts,vec![json!("hello"),json!("first"),json!("after reconnect")]);break}}
 assert_eq!(*cursors.lock().unwrap(),vec![json!(0),json!(1),json!(2)]);
 assert_eq!(bounded.load(Ordering::Relaxed),1,"the held envelope is reused across reconnects");
 writeln!(input,"{}",json!({"op":"quit"})).unwrap();child.wait().unwrap();stop.store(true,Ordering::Relaxed);server.join().unwrap();fs::remove_dir_all(root).unwrap();
}
